#!/usr/bin/env python3
"""Cliente JSON-RPC para zlib-mcp via stdio — suporta as 4 contas.

Uso:
  zlib-cli.py limits|search QUERY|download BOOK_ID HASH [ACCOUNT]
  zlib-cli.py list-accounts
  zlib-cli.py status    # checa cota das 4 contas

Se ACCOUNT não for passada, usa round-robin via arquivo de estado.

Credenciais vêm de:
  zlib (zlib1 / principal): remix_id+key do opencode.json
  zlib2/zlib3/zlib4: remix_id+key do ~/.zlib-mcp/credentials.json (cacheado)
"""
import json
import os
import subprocess
import sys
import tempfile

ZLIBCREDS_JSON = "/home/opencode/.zlib-mcp/credentials.json"
OPENCODE_JSON = "/home/opencode/.config/opencode/opencode.json"
DOWNLOAD_DIR = "/home/opencode/study-agent/data/biblioteca/_incoming"
STATE_FILE = "/home/opencode/.zlib-mcp/.rr-state"
CACHE_FILE = "/home/opencode/.zlib-mcp/.account-env-cache.json"

# Mapeamento alias ↔ mcp_name
ACCOUNT_ALIASES = {
    "zlib": "principal",
    "zlib2": "conta-b",
    "zlib3": "conta-c",
    "zlib4": "conta-d",
}

ACCOUNT_NAMES = ["zlib", "zlib2", "zlib3", "zlib4"]


def load_account_envs():
    """Carrega credenciais das 4 contas. Cache em disco."""
    if os.path.exists(CACHE_FILE):
        try:
            return json.load(open(CACHE_FILE))
        except Exception:
            pass

    envs = {}
    # zlib1: do opencode.json
    if os.path.exists(OPENCODE_JSON):
        with open(OPENCODE_JSON) as f:
            cfg = json.load(f)
        zlib_cfg = cfg.get("mcp", {}).get("zlib", {})
        zlib_env = zlib_cfg.get("environment", {})
        envs["zlib"] = {
            "ZLIB_REMIX_ID": zlib_env.get("ZLIB_REMIX_ID", ""),
            "ZLIB_REMIX_KEY": zlib_env.get("ZLIB_REMIX_KEY", ""),
        }
    # zlib2/3/4: do credentials.json (cacheado)
    if os.path.exists(ZLIBCREDS_JSON):
        with open(ZLIBCREDS_JSON) as f:
            creds = json.load(f)
        accounts = creds.get("accounts", {})
        # Mapear email → mcp_name
        email_to_mcp = {
            "robertinho1190@gmail.com": "zlib2",
            "ipbfcomunicacao@gmail.com": "zlib3",
            "osannaisjornal@gmail.com": "zlib4",
        }
        for email, mcp_name in email_to_mcp.items():
            if email in accounts:
                envs[mcp_name] = {
                    "ZLIB_REMIX_ID": accounts[email]["remixId"],
                    "ZLIB_REMIX_KEY": accounts[email]["remixKey"],
                }

    os.makedirs(os.path.dirname(CACHE_FILE), exist_ok=True)
    with open(CACHE_FILE, "w") as f:
        json.dump(envs, f)
    return envs


def get_account_env(account: str) -> dict:
    envs = load_account_envs()
    if account not in envs:
        raise RuntimeError(f"credenciais não encontradas para {account}")
    base = {"PATH": os.environ.get("PATH", ""), "ZLIB_DOWNLOAD_DIR": DOWNLOAD_DIR}
    return {**base, **envs[account]}


def call_tool(account: str, tool_name: str, arguments: dict, timeout: int = 60):
    env = get_account_env(account)
    proc = subprocess.Popen(
        ["npx", "-y", "zlib-mcp@0.1.2"],
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=env,
        text=True,
    )

    def send(msg):
        proc.stdin.write(json.dumps(msg) + "\n")
        proc.stdin.flush()

    def recv():
        line = proc.stdout.readline()
        if not line:
            err = proc.stderr.read()
            raise RuntimeError(f"server closed. stderr: {err}")
        return json.loads(line)

    send({
        "jsonrpc": "2.0", "id": 1, "method": "initialize",
        "params": {
            "protocolVersion": "2024-11-05",
            "capabilities": {},
            "clientInfo": {"name": "bibliotecario", "version": "3.0"},
        },
    })
    recv()

    send({"jsonrpc": "2.0", "method": "notifications/initialized"})

    send({
        "jsonrpc": "2.0", "id": 2, "method": "tools/call",
        "params": {"name": tool_name, "arguments": arguments},
    })
    result = recv()

    proc.terminate()
    try:
        proc.wait(timeout=5)
    except subprocess.TimeoutExpired:
        proc.kill()

    return result


def get_round_robin_account() -> str:
    accounts = ACCOUNT_NAMES
    if os.path.exists(STATE_FILE):
        try:
            state = json.load(open(STATE_FILE))
            idx = state.get("idx", 0)
        except Exception:
            idx = 0
    else:
        idx = 0
    account = accounts[idx % len(accounts)]
    new_idx = idx + 1
    os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)
    with open(STATE_FILE, "w") as f:
        json.dump({"idx": new_idx}, f)
    return account


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Uso: zlib-cli.py limits|search QUERY|download BOOK_ID HASH|status|list-accounts [ACCOUNT]", file=sys.stderr)
        sys.exit(1)

    cmd = sys.argv[1]
    account = sys.argv[-1] if sys.argv[-1] in ACCOUNT_NAMES else None

    if cmd == "limits":
        if not account:
            account = get_round_robin_account()
        sys.stderr.write(f"[usando {account}]\n")
        print(json.dumps(call_tool(account, "zlib_limits", {}), indent=2, ensure_ascii=False))
    elif cmd == "search":
        query = sys.argv[2]
        args = {"query": query, "limit": 5}
        if not account:
            account = get_round_robin_account()
        sys.stderr.write(f"[usando {account}]\n")
        print(json.dumps(call_tool(account, "zlib_search", args), indent=2, ensure_ascii=False))
    elif cmd == "download":
        book_id = sys.argv[2]
        hash_val = sys.argv[3] if len(sys.argv) > 3 else None
        if not hash_val or hash_val in ACCOUNT_NAMES:
            print("ERRO: download precisa de BOOK_ID e HASH (e opcional ACCOUNT)", file=sys.stderr)
            sys.exit(1)
        if not account:
            account = get_round_robin_account()
        sys.stderr.write(f"[usando {account}]\n")
        print(json.dumps(call_tool(account, "zlib_download", {"book_id": book_id, "hash": hash_val}), indent=2, ensure_ascii=False))
    elif cmd == "list-accounts":
        envs = load_account_envs()
        for acc in ACCOUNT_NAMES:
            if acc in envs:
                print(f"  {acc} ({ACCOUNT_ALIASES[acc]}): OK (remix_id={envs[acc].get('ZLIB_REMIX_ID', '?')[:4]}***)")
            else:
                print(f"  {acc} ({ACCOUNT_ALIASES[acc]}): FALTA")
    elif cmd == "status":
        # checa cota das 4 contas
        for acc in ACCOUNT_NAMES:
            try:
                r = call_tool(acc, "zlib_limits", {})
                text = r.get("result", {}).get("content", [{}])[0].get("text", "{}")
                d = json.loads(text)
                print(f"  {acc}: today={d.get('downloads_today')} remaining={d.get('downloads_remaining')}/limit={d.get('downloads_limit')}")
            except Exception as e:
                print(f"  {acc}: ERRO — {e}")
    else:
        print(f"Comando desconhecido: {cmd}", file=sys.stderr)
        sys.exit(1)

