"""Cliente JSON-RPC para zlib-mcp via stdio — paths desta instalacao (picoclaw).

Uso:
  zlib-local.py limits|search QUERY|download BOOK_ID HASH [ACCOUNT]
  zlib-local.py status | list-accounts
"""
import json
import os
import subprocess
import sys

CREDS_CACHE = "/opt/opencode/data/.zlib-mcp/.account-env-cache.json"
DOWNLOAD_DIR = "/home/study-agent/data/biblioteca/_incoming"
STATE_FILE = "/opt/opencode/data/.zlib-mcp/.rr-state"
MCP_PKG = "zlib-mcp@0.1.2"

ACCOUNT_NAMES = ["zlib", "zlib2", "zlib3", "zlib4"]
ALIASES = {"zlib": "principal", "zlib2": "conta-b", "zlib3": "conta-c", "zlib4": "conta-d"}


def load_account_envs():
    envs = {}
    if os.path.exists(CREDS_CACHE):
        try:
            envs = json.load(open(CREDS_CACHE))
        except Exception:
            envs = {}
    if not envs:
        # fallback: ler do yaml de credenciais do perfil
        import re
        p = "/home/study-agent/data/perfil/bibliotecario/zlib-credentials.yaml"
        txt = open(p, encoding="utf-8").read()
        blocks = txt.split("- alias:")
        order = ["zlib", "zlib2", "zlib3", "zlib4"]
        for i, b in enumerate(blocks[1:]):
            rid = re.search(r"remix_id:\s*'?([0-9]+)'?", b)
            rkey = re.search(r"remix_key:\s*'?([A-Za-z0-9]+)'?", b)
            if rid and rkey and i < len(order):
                envs[order[i]] = {"ZLIB_REMIX_ID": rid.group(1), "ZLIB_REMIX_KEY": rkey.group(1)}
    return envs


def get_account_env(account):
    envs = load_account_envs()
    if account not in envs:
        raise RuntimeError(f"credenciais nao encontradas para {account} (cache: {list(envs)})")
    base = {"PATH": os.environ.get("PATH", "") + ":/usr/bin:/usr/local/bin",
            "ZLIB_DOWNLOAD_DIR": DOWNLOAD_DIR,
            "HOME": os.environ.get("HOME", "/root")}
    return {**base, **envs[account]}


def call_tool(account, tool_name, arguments, timeout=180):
    env = get_account_env(account)
    proc = subprocess.Popen(["npx", "-y", MCP_PKG], stdin=subprocess.PIPE,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, text=True)

    def send(msg):
        proc.stdin.write(json.dumps(msg) + "\n")
        proc.stdin.flush()

    def recv():
        line = proc.stdout.readline()
        if not line:
            err = proc.stderr.read()
            raise RuntimeError(f"server closed. stderr: {err[:600]}")
        return json.loads(line)

    send({"jsonrpc": "2.0", "id": 1, "method": "initialize",
          "params": {"protocolVersion": "2024-11-05", "capabilities": {},
                     "clientInfo": {"name": "bibliotecario", "version": "3.0"}}})
    recv()
    send({"jsonrpc": "2.0", "method": "notifications/initialized"})
    send({"jsonrpc": "2.0", "id": 2, "method": "tools/call",
          "params": {"name": tool_name, "arguments": arguments}})
    result = recv()
    try:
        proc.terminate()
        proc.wait(timeout=5)
    except Exception:
        proc.kill()
    return result


def rr_account():
    idx = 0
    if os.path.exists(STATE_FILE):
        try:
            idx = json.load(open(STATE_FILE)).get("idx", 0)
        except Exception:
            idx = 0
    acc = ACCOUNT_NAMES[idx % len(ACCOUNT_NAMES)]
    os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)
    json.dump({"idx": idx + 1}, open(STATE_FILE, "w"))
    return acc


def text_of(result):
    try:
        return result.get("result", {}).get("content", [{}])[0].get("text", "")
    except Exception:
        return json.dumps(result)[:1500]


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Uso: zlib-local.py limits|search QUERY|download BOOK_ID HASH [ACCOUNT]", file=sys.stderr)
        sys.exit(1)
    cmd = sys.argv[1]
    account = sys.argv[-1] if sys.argv[-1] in ACCOUNT_NAMES else None
    try:
        if cmd == "search":
            q = sys.argv[2]
            account = account or rr_account()
            print(f"[conta: {account}]", file=sys.stderr)
            r = call_tool(account, "zlib_search", {"query": q, "limit": 10})
            print(text_of(r))
        elif cmd == "download":
            book_id, hash_val = sys.argv[2], sys.argv[3]
            account = account or rr_account()
            print(f"[conta: {account}]", file=sys.stderr)
            r = call_tool(account, "zlib_download", {"book_id": book_id, "hash": hash_val})
            print(text_of(r))
        elif cmd == "limits":
            account = account or rr_account()
            r = call_tool(account, "zlib_limits", {})
            print(text_of(r))
        elif cmd == "status":
            for acc in ACCOUNT_NAMES:
                try:
                    r = call_tool(acc, "zlib_limits", {})
                    d = json.loads(text_of(r))
                    print(f"  {acc}: today={d.get('downloads_today')} remaining={d.get('downloads_remaining')}/{d.get('downloads_limit')}")
                except Exception as e:
                    print(f"  {acc}: ERRO — {str(e)[:150]}")
        elif cmd == "list-accounts":
            envs = load_account_envs()
            for acc in ACCOUNT_NAMES:
                ok = "OK" if acc in envs else "FALTA"
                print(f"  {acc} ({ALIASES[acc]}): {ok}")
        else:
            print(f"Comando desconhecido: {cmd}", file=sys.stderr)
            sys.exit(1)
    except Exception as e:
        print(f"ERRO: {e}", file=sys.stderr)
        sys.exit(2)
